fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).expect("hex digits"))
        .collect()
}

/// The test data of "clan" with practically no deaths, the window from 16 and no
/// separation.
fn emigration_data() -> Data {
    let (mut calibration, genome_map) =
        common::death_files(1e-9, None, common::repository_diseases());
    let mut demography = common::demography();
    common::window_fertility(&mut calibration, &mut demography, 0.25);
    calibration["fertility"]["window"]["from"]["value"] = serde_json::json!(16.0);
    Data::new(common::definitions_with(demography, calibration, genome_map).expect("definitions"))
        .expect("checked")
}

fn founder(born: i64, sex: Sex) -> Founder {
    Founder {
        born: SimTime::from_secs(born),
        sex,
        alleles: Vec::new(),
    }
}

fn emigration_start(seed: u64, capacity: Option<u64>) -> Input {
    Input::Start(Start {
        world_seed: seed,
        founder_tag: DataId::new("test:emigration33").expect("valid"),
        world_params: WorldParams {
            hereditary_diseases: false,
            nutrition: Vec::new(),
        },
        founders: vec![
            founder(-16 * Y, Sex::Female),
            founder(-18 * Y, Sex::Male),
            founder(-(16 * Y + 91 * DAY), Sex::Female),
            founder(-19 * Y, Sex::Male),
            founder(-(16 * Y + 182 * DAY), Sex::Female),
            founder(-20 * Y, Sex::Male),
            founder(-10 * Y, Sex::Male),
            founder(-8 * Y, Sex::Female),
        ],
        couples: vec![
            Couple { woman: 0, man: 1 },
            Couple { woman: 2, man: 3 },
            Couple { woman: 4, man: 5 },
        ],
        capacity,
        pool: None,
    })
}

struct Run {
    world: World,
    out: YearOut,
    log: Vec<LogEntry>,
}

impl Run {
    fn start(seed: u64, capacity: Option<u64>) -> Run {
        let mut world = World::new(emigration_data());
        world
            .submit(emigration_start(seed, capacity))
            .expect("accepted");
        let log = world.take_log();
        Run {
            world,
            out: YearOut::default(),
            log,
        }
    }

    fn emigration() -> Run {
        Run::start(0xff, Some(CAPACITY))
    }

    fn play(&mut self, until: i64) {
        self.world
            .advance_until(&mut self.out, SimTime::from_secs(until), &mut |_| false);
        self.log.extend(self.world.take_log());
    }

    fn save(&self) -> Vec<u8> {
        self.world.save(&self.out.year_hashes).expect("saves")
    }

    fn year_hashes(&self) -> Vec<u64> {
        self.out.year_hashes.iter().map(|y| y.hash).collect()
    }

    /// The entries from `from` on, against the reference: the bytes of each, and its JSON
    /// form where the reference gives it.
    fn assert_entries(&self, from: usize, expected: &[(&str, Option<&str>)]) {
        let entries = &self.log[from..];
        assert_eq!(entries.len(), expected.len(), "entries");
        for (entry, (bytes, json)) in entries.iter().zip(expected) {
            assert_eq!(
                postcard::to_allocvec(entry).expect("encodes"),
                hex(bytes),
                "entry {}",
                serde_json::to_string(entry).expect("json")
            );
            if let Some(json) = json {
                assert_eq!(serde_json::to_string(entry).expect("json"), *json);
            }
        }
    }

    /// Plays up to the second before `at` (its save against `before`), then that second
    /// (its entries and its save against the reference); the save loads.
    fn second(&mut self, at: i64, before: &str, expected: &[(&str, Option<&str>)], after: &str) {
        self.play(at - 1);
        assert_eq!(self.save(), hex(before));
        let from = self.log.len();
        self.play(at);
        self.assert_entries(from, expected);
        assert_eq!(self.save(), hex(after));
        assert_loads(&self.save());
    }
}

/// The save loads and the loaded world saves the same bytes (ADR-0006 section 6): the load
/// checks of the emigration accept what the rule gives.
fn assert_loads(bytes: &[u8]) {
    let (world, years) = World::load(bytes, emigration_data()).expect("loads");
    assert_eq!(world.save(&years).expect("saves"), bytes);
}

#[test]
fn the_test_data_of_emigration() {
    assert_eq!(emigration_data().hash(), DATA_HASH);
}

/// `Start` with a capacity: the record of the input log carries it, and the yearly event
/// is planned in the last second of year 0 after the market round.
#[test]
fn start_with_a_capacity_plans_the_yearly_event() {
    let run = Run::emigration();
    let record = &run.world.input_log()[0];
    assert_eq!(
        postcard::to_allocvec(record).expect("encodes"),
        hex(START_RECORD)
    );
    run.assert_entries(0, &START_ENTRIES);
    assert_eq!(run.save(), hex(SAVE_AFTER_START));
    assert_loads(&run.save());
}

/// The end of year 2: a couple leaves with its dependent children, another with the woman
/// pregnant (her pregnancy goes with her); the two children alone in their households have
/// no member of 18 and draw nothing.
#[test]
fn households_leave_whole_with_their_children_and_pregnancies() {
    let mut run = Run::emigration();
    run.second(
        FIRST_AT,
        SAVE_BEFORE_FIRST,
        &FIRST_ENTRIES,
        SAVE_AFTER_FIRST,
    );
}

/// The end of year 14: sim 8, grown up alone in her household, leaves alone.
#[test]
fn a_young_adult_alone_leaves_alone() {
    let mut run = Run::emigration();
    run.second(
        ALONE_AT,
        SAVE_BEFORE_ALONE,
        &ALONE_ENTRIES,
        SAVE_AFTER_ALONE,
    );
}

/// The end of year 20: household 2 leaves with sixteen children and the woman pregnant;
/// sim 14, moved out at 18, draws on her own and stays.
#[test]
fn a_moved_out_child_of_emigrants_stays() {
    let mut run = Run::emigration();
    run.second(
        ADULT_CHILD_AT,
        SAVE_BEFORE_ADULT_CHILD,
        &ADULT_CHILD_ENTRIES,
        SAVE_AFTER_ADULT_CHILD,
    );
}

/// The whole run: the year hashes, the log, the save and the pedigree at its end.
#[test]
fn emigration_runs_as_the_reference() {
    let mut run = Run::emigration();
    run.play(END);
    assert_eq!(run.year_hashes(), YEAR_HASHES);
    assert_eq!(run.log.len(), LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), LOG_HASH);
    assert_eq!(run.save(), hex(SAVE_END));
    assert_loads(&run.save());
    assert_eq!(
        serde_json::to_string(&run.world.pedigree()).expect("json"),
        END_PEDIGREE_JSON
    );
}

/// The same founders with the seed 0xfe draw otherwise: at the end of year 8 `P` is 21 =
/// 1.5 · 14, so `e` is 0.5 exactly.
#[test]
fn another_seed_draws_otherwise() {
    let mut run = Run::start(0xfe, Some(CAPACITY));
    run.play(END);
    assert_eq!(run.year_hashes(), SEED_FE_YEAR_HASHES);
    assert_eq!(run.log.len(), SEED_FE_LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), SEED_FE_LOG_HASH);
    assert_eq!(run.save(), hex(SEED_FE_SAVE_END));
    assert_loads(&run.save());
}

/// Without a capacity nothing is planned and nobody leaves: the population grows to 67.
#[test]
fn without_a_capacity_nobody_leaves() {
    let mut run = Run::start(0xff, None);
    run.play(END);
    assert_eq!(run.year_hashes(), WITHOUT_CAPACITY_YEAR_HASHES);
    assert_eq!(run.log.len(), WITHOUT_CAPACITY_LOG_ENTRIES);
    assert_eq!(log_hash(&run.log), WITHOUT_CAPACITY_LOG_HASH);
    assert_eq!(run.world.state().living(), 67);
}

/// Saves the rule cannot reach are rejected: household 1 left a second before the year
/// end; sim 11 left alone while his household goes on; a birthday is still planned for an
/// emigrant; the yearly event is missing; the event stands at another second. Review
/// findings: a partnership ended by emigration whose partner left at another year end,
/// from another household, or still lives; a founder emigrated at −1, before the start.
/// Mutation probe: a household without a member of 18 or more that emigrated.
#[test]
fn a_save_against_the_emigration_is_rejected() {
    for (case, bytes) in LOAD_REJECTED {
        assert_eq!(
            World::load(&hex(bytes), emigration_data()).err(),
            Some(LoadError::Inconsistent),
            "{case}"
        );
    }
}
